using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;
using ShipmentTracker.Data.Models;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(s =>
                s.TrackingNumber.ToLower().Contains(term) ||
                s.Destination.ToLower().Contains(term) ||
                s.Origin.ToLower().Contains(term) ||
                (s.RecipientName != null && s.RecipientName.ToLower().Contains(term)));
        }

        return await query
            .OrderByDescending(s => s.CreatedDate)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<TrackingResult> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        if (shipment is null)
            return new TrackingResult { Found = false };

        return new TrackingResult { Found = true, Shipment = shipment.ToDto() };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = request.Origin,
            Destination = request.Destination,
            RecipientName = request.RecipientName,
            Description = request.Description,
            EstimatedDelivery = request.EstimatedDelivery,
            Status = ShipmentStatus.Pending,
            CreatedDate = DateTime.UtcNow
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

    public async Task UpdateStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found");

        shipment.Status = request.Status;
        await db.SaveChangesAsync();
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found");

        db.Shipments.Remove(shipment);
        await db.SaveChangesAsync();
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}";
    }
}

