@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">📦 ShipmentTracker</h1>
        <p class="lead text-muted">Real-time logistics tracking for dispatchers and customers</p>
    </div>

    <div class="row g-4 justify-content-center">
        <div class="col-md-5">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">🔍 Track a Shipment</h3>
                    <p class="card-text">Enter your tracking number to check shipment status and estimated delivery.</p>
                    <div class="input-group mb-3">
                        <input type="text" class="form-control" placeholder="e.g. SHP-20260601-10001"
                               @bind="trackingInput" @bind:event="oninput"
                               @onkeydown="HandleTrackKeyDown" />
                        <button class="btn btn-primary" @onclick="GoToTracking">Track</button>
                    </div>
                </div>
            </div>
        </div>

        <div class="col-md-5">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">📋 Dispatcher Dashboard</h3>
                    <p class="card-text">View all shipments, update statuses, and manage logistics operations.</p>
                    <AuthorizeView>
                        <Authorized>
                            <a href="shipments" class="btn btn-success">Open Dashboard</a>
                        </Authorized>
                        <NotAuthorized>
                            <a href="Account/Login" class="btn btn-outline-success">Login to Access</a>
                        </NotAuthorized>
                    </AuthorizeView>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private string trackingInput = string.Empty;

    private void GoToTracking()
    {
        if (!string.IsNullOrWhiteSpace(trackingInput))
        {
            Navigation.NavigateTo($"track?number={Uri.EscapeDataString(trackingInput.Trim())}");
        }
    }

    private void HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            GoToTracking();
    }
}

@page "/track"

<PageTitle>Track Shipment</PageTitle>

<div class="container py-4">
    <h2>🔍 Track Your Shipment</h2>
    <p class="text-muted">Enter your tracking number to see current status and estimated delivery.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (hasSearched && result is not null)
    {
        @if (result.Found && result.Shipment is not null)
        {
            var s = result.Shipment;
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Shipment @s.TrackingNumber</h5>
                    <span class="badge @GetStatusBadgeClass(s.Status) fs-6">@FormatStatus(s.Status)</span>
                </div>
                <div class="card-body">
                    <div class="row g-3">
                        <div class="col-md-6">
                            <strong>Origin:</strong>
                            <p>@s.Origin</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Destination:</strong>
                            <p>@s.Destination</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Recipient:</strong>
                            <p>@(s.RecipientName ?? "—")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Description:</strong>
                            <p>@(s.Description ?? "—")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Shipped Date:</strong>
                            <p>@s.CreatedDate.ToString("MMM dd, yyyy")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Estimated Delivery:</strong>
                            <p class="@(IsOverdue(s) ? "text-danger fw-bold" : "")">
                                @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Not set")
                                @if (IsOverdue(s))
                                {
                                    <span> (Overdue)</span>
                                }
                            </p>
                        </div>
                    </div>

                    <!-- Progress visualization -->
                    <div class="mt-4">
                        <h6>Shipment Progress</h6>
                        <div class="progress" style="height: 30px;">
                            <div class="progress-bar @GetProgressBarClass(s.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(s.Status))%">
                                @FormatStatus(s.Status)
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning">
                <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
                Please check the number and try again.
            </div>
        }
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "number")]
    private string? QueryNumber { get; set; }

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private TrackingResult? result;
    private bool hasSearched;
    private bool isLoading;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(QueryNumber))
        {
            trackingNumber = QueryNumber;
            await TrackShipment();
