    private bool showCreateForm;
    private bool isCreating;
    private string? createError;
    private CreateShipmentRequest newShipment = new();
    private DateTime? estimatedDeliveryDate;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetShipmentsAsync(statusFilter, searchTerm);
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task RefreshList() => await LoadShipments();

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Origin and Destination are required.";
            return;
        }

        isCreating = true;
        createError = null;
        try
        {
            newShipment.EstimatedDelivery = estimatedDeliveryDate.HasValue
                ? DateTime.SpecifyKind(estimatedDeliveryDate.Value, DateTimeKind.Utc)
                : null;
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new();
            estimatedDeliveryDate = null;
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, new UpdateShipmentStatusRequest { Status = newStatus });
            shipment.Status = newStatus;
        }
    }

    private async Task DeleteShipment(ShipmentDto shipment)
    {
        await ShipmentService.DeleteShipmentAsync(shipment.Id);
        shipments?.Remove(shipment);
