<PageTitle>Track Shipment</PageTitle>

<div class="container py-4">
    <h2>🔍 Track Your Shipment</h2>
    <p class="text-muted">Enter your tracking number to see current status and estimated delivery.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (hasSearched && result is not null)
    {
        @if (result.Found && result.Shipment is not null)
        {
            var s = result.Shipment;
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Shipment @s.TrackingNumber</h5>
                    <span class="badge @GetStatusBadgeClass(s.Status) fs-6">@FormatStatus(s.Status)</span>
                </div>
                <div class="card-body">
                    <div class="row g-3">
                        <div class="col-md-6">
                            <strong>Origin:</strong>
                            <p>@s.Origin</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Destination:</strong>
                            <p>@s.Destination</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Recipient:</strong>
                            <p>@(s.RecipientName ?? "—")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Description:</strong>
                            <p>@(s.Description ?? "—")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Shipped Date:</strong>
                            <p>@s.CreatedDate.ToString("MMM dd, yyyy")</p>
                        </div>
                        <div class="col-md-6">
                            <strong>Estimated Delivery:</strong>
                            <p class="@(IsOverdue(s) ? "text-danger fw-bold" : "")">
                                @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Not set")
                                @if (IsOverdue(s))
                                {
                                    <span> (Overdue)</span>
                                }
                            </p>
                        </div>
                    </div>

                    <!-- Progress visualization -->
                    <div class="mt-4">
                        <h6>Shipment Progress</h6>
                        <div class="progress" style="height: 30px;">
                            <div class="progress-bar @GetProgressBarClass(s.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(s.Status))%">
                                @FormatStatus(s.Status)
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning">
                <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
                Please check the number and try again.
            </div>
        }
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "number")]
    private string? QueryNumber { get; set; }

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private TrackingResult? result;
    private bool hasSearched;
    private bool isLoading;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(QueryNumber))
        {
            trackingNumber = QueryNumber;
            await TrackShipment();
        }
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        searchedNumber = trackingNumber.Trim();
        try
        {
            result = await ShipmentService.TrackShipmentAsync(searchedNumber);
            hasSearched = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            _ = TrackShipment();
    }

    private static bool IsOverdue(ShipmentDto s) =>
        s.EstimatedDelivery.HasValue &&
        s.EstimatedDelivery.Value < DateTime.UtcNow &&
        s.Status != ShipmentStatus.Delivered;

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Cancelled => "Cancelled",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}
