                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Create Shipment
                        </button>
                    </div>
                </div>
                @if (!string.IsNullOrEmpty(createError))
                {
                    <div class="alert alert-danger mt-2 mb-0">@createError</div>
                }
            </div>
        </div>
    }

    <!-- Filters -->
    <div class="row g-2 mb-3">
        <div class="col-md-3">
            <input type="text" class="form-control" placeholder="Search shipments..."
                   @bind="searchTerm" @bind:event="oninput" @bind:after="LoadShipments" />
        </div>
        <div class="col-md-2">
            <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
