            <div class="spinner-border" role="status"></div>
            <p class="mt-2 text-muted">Loading shipments...</p>
        </div>
    }
    else if (shipments is null || shipments.Count == 0)
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover align-middle">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Recipient</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in shipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td>@(s.RecipientName ?? "—")</td>
                            <td>
                                <span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span>
                            </td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>
                                <div class="d-flex gap-1 align-items-center">
                                    <select class="form-select form-select-sm" style="width: auto;"
                                            value="@s.Status"
                                            @onchange="e => UpdateStatus(s, e)">
                                        @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@st" selected="@(st == s.Status)">@FormatStatus(st)</option>
                                        }
                                    </select>
                                    <button class="btn btn-sm btn-outline-danger" title="Delete"
                                            @onclick="() => DeleteShipment(s)">🗑</button>
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @shipments.Count shipment(s)</p>
    }
</div>

